def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        safe_bid = DAILY_SALARY * 0.28
        if hp <= 2 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.6
        return float(min(budget, safe_bid))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= 500:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0)))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    danger = 0
    if hp <= 2:
        danger = 2
    elif hp <= 4 or no_water_days >= 1:
        danger = 1

    if danger == 2:
        bid = max(DAILY_SALARY * 0.92, highest_prev + 2.0)
    elif danger == 1:
        if scarcity == 2:
            bid = max(DAILY_SALARY * 0.82, highest_prev + 1.5)
        elif scarcity == 1:
            bid = max(DAILY_SALARY * 0.68, avg_prev + 1.0)
        else:
            bid = DAILY_SALARY * 0.56
    else:
        if scarcity == 2:
            if highest_prev > 130:
                bid = DAILY_SALARY * 0.34
            else:
                bid = max(DAILY_SALARY * 0.52, min(highest_prev + 1.0, DAILY_SALARY * 0.78))
        elif scarcity == 1:
            if highest_prev > 140:
                bid = DAILY_SALARY * 0.26
            else:
                bid = max(DAILY_SALARY * 0.38, min(avg_prev + 0.5, DAILY_SALARY * 0.6))
        else:
            bid = DAILY_SALARY * 0.22

    if rich_opp >= 2 and scarcity >= 1 and danger == 0 and highest_prev > 120:
        bid = min(bid, DAILY_SALARY * 0.3)

    if urgent_opp >= 2 and danger >= 1:
        bid = max(bid, highest_prev + 2.5)

    if day >= 8 and hp >= 6 and budget < 220:
        bid = min(bid, DAILY_SALARY * 0.42)

    bid = max(0.0, min(float(bid), float(budget)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Reaction to yesterday bids (immediate only)
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how tight the market is: supply relative to our need.
    # If supply is low, competition likely higher.
    tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    tightness = max(0.0, min(1.0, tightness))

    # Base bid: we aim to secure water without chasing the very highest bids.
    # If others were bidding very high yesterday, we bid around a fraction of DAILY_SALARY plus a small bump.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure: ensure we get water if our hp is not critical.
        if hp > 3.0:
            target = DAILY_SALARY * (0.30 + 0.25 * tightness) + 0.15 * highest_prev_bid
        else:
            target = DAILY_SALARY * (0.75 + 0.15 * tightness) + 0.10 * highest_prev_bid
    else:
        # Moderate pressure: bid enough to be competitive but not maximal.
        target = max(DAILY_SALARY * (0.45 + 0.20 * tightness), highest_prev_bid * 0.60 + 5.0)

    # If we've already gone without water, escalate quickly.
    if no_water_days >= 1:
        target *= 1.25
    if no_water_days >= 2:
        target *= 1.45

    # If we're in danger, bid more aggressively.
    if hp <= 2.0:
        target = max(target, DAILY_SALARY * (0.85 + 0.1 * tightness))

    # Budget and safety bounds.
    target = max(0.0, target)
    # Ensure we don't bid more than we can afford.
    if budget <= 0.0:
        return 0.0
    if target > budget:
        target = budget

    # Never bid above a reasonable cap relative to supply competition.
    # (Helps avoid getting into bidding wars.)
    cap = DAILY_SALARY * (1.1 + 0.3 * tightness)
    if target > cap:
        target = cap

    return float(target)

